func (this *Test_org_eclipse_swt_graphics_ImageData) Test_scaledToII() {
	var imageDimension int32 = 8
	var rgbs []*swt.RGB = []*swt.RGB{swt.NewRGB(0, 0, 0), swt.NewRGB(255, 255, 255)}
	var pixelData []int8 = make([]int8, (imageDimension*imageDimension)/8)
	pixelData[0] = int8(0x4F)
	this.imageData = swt.NewImageDataWidthHeightDepthPaletteScanlinePadData(imageDimension, imageDimension, 1, swt.NewPaletteData(rgbs), 1, pixelData)
	var scaledImageData *swt.ImageData = this.imageData.ScaledTo(-imageDimension, -imageDimension)
	var scaledPixelData []int8 = make([]int8, imageDimension)
	scaledImageData.GetPixels(0, imageDimension-1, int32(len(scaledPixelData)), scaledPixelData, 0)
	var expectedPixelData []int8 = []int8{int8(0x1), int8(0x1), int8(0x1), int8(0x1), int8(0), int8(0), int8(0x1), int8(0)}
	junit.AssertArrayEquals(expectedPixelData, scaledPixelData)
	scaledImageData = this.imageData.ScaledTo(imageDimension*10, imageDimension)
	scaledPixelData = make([]int8, imageDimension*10)
	scaledImageData.GetPixels(0, 0, int32(len(scaledPixelData)), scaledPixelData, 0)
	junit.AssertEquals(int32(0), int32(int32(scaledPixelData[0])))
	junit.AssertEquals(int32(0), int32(int32(scaledPixelData[1])))
	scaledImageData = this.imageData.ScaledTo(imageDimension, imageDimension*10)
	scaledPixelData = make([]int8, imageDimension)
	scaledImageData.GetPixels(0, 0, int32(len(scaledPixelData)), scaledPixelData, 0)
	expectedPixelData = []int8{int8(0), int8(0x1), int8(0), int8(0), int8(0x1), int8(0x1), int8(0x1), int8(0x1)}
	junit.AssertArrayEquals(expectedPixelData, scaledPixelData)
}

